// As duas sintaxes são equivalentes
const nomes: string[] = ["Ana", "Bruno"];
const apelidos: Array<string> = ["Silva", "Costa"];

// O tipo do elemento pode ser qualquer tipo
const medidas: number[] = [1.5, 2.25];
const ativos: boolean[] = [true, false];

// Com valor inicial, a inferência dispensa a anotação
const cidades = ["Porto", "Braga"]; // string[]

// Um array anotado continua a ser verificado a cada operação
const destinos: string[] = [];
destinos.push("Lisboa");
// @ts-expect-error um string[] não aceita números
destinos.push(42);

console.log(nomes, apelidos, medidas, ativos, cidades, destinos);

// Um array cujos elementos podem ser string OU number, misturados à vontade
const registos: (string | number)[] = ["manhã", 18.5, "tarde", 21];

// Uma união de dois tipos de array: ou é todo de strings, ou é todo de números
let coluna: string[] | number[] = ["a", "b"];
coluna = [1, 2];
// @ts-expect-error não é string[] nem number[]: misturar não é permitido
coluna = ["a", 1];

// Os parênteses não são decorativos
const semParenteses: string | number[] = "sou uma string";

// Arrays multidimensionais
const grelha: number[][] = [
  [1, 2, 3],
  [4, 5, 6],
];
const primeiraLinha = grelha[0]; // number[]

// Inferência a partir de um literal misto
const inferido = [1, "dois", true]; // (string | number | boolean)[]

console.log(registos, coluna, semParenteses, primeiraLinha, inferido);

// Uma tupla: exatamente dois elementos, string na posição 0 e number na posição 1
const par: [string, number] = ["idade", 42];
const chave = par[0]; // string
const valor = par[1]; // number

// @ts-expect-error o comprimento faz parte do tipo: falta o segundo elemento
const incompleto: [string, number] = ["idade"];

// @ts-expect-error a ordem dos tipos não corresponde
const trocado: [string, number] = [42, "idade"];

// Tuplas nomeadas: os nomes são documentação, o tipo continua a ser o mesmo
type Coordenada = [latitude: number, longitude: number];
const porto: Coordenada = [41.1579, -8.6291];

// Um literal nunca é inferido como tupla: sem anotação dá um array
const parecido = ["idade", 42]; // (string | number)[]

console.log(chave, valor, incompleto, trocado, porto, parecido);

// O padrão do useState: devolver um par de valor e função que o altera
function criarContador(inicial: number): [number, (novo: number) => void] {
  let atual = inicial;
  const definir = (novo: number): void => {
    atual = novo;
  };
  return [atual, definir];
}

const [contador, definirContador] = criarContador(0);
definirContador(contador + 1);

// Elemento opcional: o terceiro pode faltar
type Rgb = [number, number, number?];
const vermelho: Rgb = [255, 0, 0];
const parcial: Rgb = [255, 0];
const canalAzul = vermelho[2]; // number | undefined

// Elemento rest: as primeiras posições são fixas, o resto é livre
type Registo = [nivel: string, ...mensagens: string[]];
const aviso: Registo = ["warn", "disco quase cheio"];
const falha: Registo = ["error", "falhou", "a repetir", "desisti"];

console.log(contador, parcial, canalAzul, aviso, falha);

// As duas formas de escrever um array só de leitura
const dias: readonly string[] = ["seg", "ter", "qua"];
const meses: ReadonlyArray<string> = ["jan", "fev"];

// @ts-expect-error um array readonly não tem push
dias.push("qui");
// @ts-expect-error nem pop, shift, splice ou sort
meses.pop();
// @ts-expect-error nem atribuição por índice
dias[0] = "dom";

// Continua a poder ler, percorrer e produzir arrays novos
const maiusculas = dias.map((d) => d.toUpperCase()); // string[] mutável
const alargado = [...dias, "qui"]; // string[] mutável

// Um array mutável entra onde se espera readonly; o inverso não
const mutavel: string[] = ["a", "b"];
const protegido: readonly string[] = mutavel;
// @ts-expect-error perder-se-ia a garantia de não alteração
const outra: string[] = protegido;

console.log(meses, maiusculas, alargado, protegido, outra);

// Sem as const: tipo largo e array mutável
const cores = ["vermelho", "verde"]; // string[]
cores.push("azul");

// Com as const: tupla readonly de tipos literais
const estados = ["ativo", "inativo", "suspenso"] as const;
// tipo: readonly ["ativo", "inativo", "suspenso"]

// @ts-expect-error a tupla produzida por as const é readonly
estados.push("apagado");

const primeiro = estados[0]; // "ativo", e não string

// O ganho prático: derivar a união dos valores a partir do array
type Estado = (typeof estados)[number]; // "ativo" | "inativo" | "suspenso"
const atual: Estado = "suspenso";
// @ts-expect-error "apagado" não consta do array
const invalido: Estado = "apagado";

console.log(cores, primeiro, atual, invalido);

const lista: string[] = ["a", "b", "c"];

// Isto compila sem um único aviso
const fora = lista[99]; // tipo declarado: string. Valor real: undefined
console.log(fora.toUpperCase()); // TypeError em tempo de execução

// Já aqui o TypeScript avisa, porque find declara que pode falhar
const encontrado = lista.find((item) => item === "z"); // string | undefined
// @ts-expect-error encontrado pode ser undefined
console.log(encontrado.toUpperCase());

// A defesa que não depende de nenhuma opção do compilador
const talvez: string | undefined = lista[1];
if (talvez !== undefined) {
  console.log(talvez.toUpperCase()); // "B"
}

