const temperaturas: number[] = [18.5, 21, 19.75];
const periodos: Array<string> = ["manhã", "tarde", "noite"];
const leituras: (string | number)[] = ["manhã", 18.5, "tarde", 21];

function media(valores: number[]): number {
  if (valores.length === 0) {
    return 0;
  }
  const total = valores.reduce((acc, valor) => acc + valor, 0);
  return total / valores.length;
}

console.log(media(temperaturas)); // 19.75
console.log(periodos.join(", ")); // "manhã, tarde, noite"
console.log(leituras.length); // 4

type Divisao = [quociente: number, resto: number];

function dividir(dividendo: number, divisor: number): Divisao {
  return [Math.floor(dividendo / divisor), dividendo % divisor];
}

const [q, r] = dividir(17, 5);
console.log(q, r); // 3 2

type Ponto = [x: number, y: number, z?: number];

function descrever(ponto: Ponto): string {
  const [x, y, z] = ponto;
  return z === undefined ? `(${x}, ${y})` : `(${x}, ${y}, ${z})`;
}

const plano: Ponto = [1, 2];
const espaco: Ponto = [1, 2, 3];

console.log(descrever(plano)); // "(1, 2)"
console.log(descrever(espaco)); // "(1, 2, 3)"

function ordenar(valores: readonly number[]): number[] {
  return [...valores].sort((a, b) => a - b);
}

const originais: readonly number[] = [3, 1, 2];
const resultado = ordenar(originais);

console.log(originais); // [3, 1, 2], intacto
console.log(resultado); // [1, 2, 3]

function tentativaErrada(valores: readonly number[]): number[] {
  // @ts-expect-error sort altera o array e não existe em readonly number[]
  return valores.sort((a: number, b: number) => a - b);
}

console.log(tentativaErrada([2, 1]));

const NIVEIS = ["debug", "info", "warn", "error"] as const;

type Nivel = (typeof NIVEIS)[number]; // "debug" | "info" | "warn" | "error"

function eNivel(valor: string): valor is Nivel {
  return (NIVEIS as readonly string[]).includes(valor);
}

function prioridade(nivel: Nivel): number {
  return NIVEIS.indexOf(nivel);
}

const entrada: string = "warn";
if (eNivel(entrada)) {
  console.log(prioridade(entrada)); // 2
}

// @ts-expect-error o as const tornou o array readonly
NIVEIS.push("fatal");

const DESCRICOES: readonly (readonly [Nivel, string])[] = [
  ["debug", "Detalhe de diagnóstico"],
  ["error", "Falha grave"],
];

for (const [nivel, texto] of DESCRICOES) {
  console.log(`${prioridade(nivel)} ${nivel}: ${texto}`);
}
